// Extract all posted keywords to avoid repeating
const postedTopics = items.map(item => item.json.topic_keyword).filter(Boolean);

// Keywords to search for trending posts
const searchKeywords = [
  'zapošljavanje mladih srbija',
  'građevinski radnici',
  'omladinska zadruga',
  'posao za mlade beograd',
  'kako zaposliti radnike',
  'gen z radnici',
  'pronalazak radnika'
];

// Pick a random keyword that we haven't posted about recently
const availableKeywords = searchKeywords.filter(kw => 
  !postedTopics.some(posted => 
    posted.toLowerCase().includes(kw.split(' ')[0].toLowerCase())
  )
);

const selectedKeyword = availableKeywords.length > 0 
  ? availableKeywords[Math.floor(Math.random() * availableKeywords.length)]
  : searchKeywords[0]; // fallback

return [{
  json: {
    search_keyword: selectedKeyword,
    posted_topics: postedTopics,
    avoid_keywords: postedTopics.join(', ')
  }
}];

// Parse Gemini response
const response = items[0].json.message?.content || items[0].json.text || "";

let parsed;
try {
  // Remove markdown code blocks if present
  const cleaned = response.replace(/```json\n?|```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Fallback if not JSON
  return [{
    json: {
      post_text: response.substring(0, 300),
      post_theme: $('Select Topic').item.json.search_keyword,
      engagement_score: 7,
      target_audience: 'company owners',
      reasoning: 'Generated content'
    }
  }];
}

return [{
  json: {
    post_text: parsed.post_text,
    post_theme: parsed.post_theme || $('Select Topic').item.json.search_keyword,
    engagement_score: parsed.engagement_score || 7,
    target_audience: parsed.target_audience || 'company owners and HR',
    reasoning: parsed.reasoning || 'AI generated',
    status: 'draft',
    post_type: 'original',
    client_id: '[OZ_AVALA_CLIENT_UUID]'
  }
}];

